import { randomUUID } from "node:crypto";
import { DomainError } from "../domain/errors";
import {
  assertCancellable,
  isOrderStatus,
  nextState,
  type Order,
  type OrderLine,
  type OrderStatus,
} from "../domain/order";
import {
  dispatch,
  release,
  reserve,
  toStockLevel,
  type Product,
  type StockLevel,
} from "../domain/product";
import type { OrderRepository, ProductRepository } from "./ports";

export class OrderService {
  constructor(
    private readonly products: ProductRepository,
    private readonly orders: OrderRepository,
  ) {}

  placeOrder(lines: readonly OrderLine[]): Order {
    if (lines.length === 0) {
      throw new DomainError("invalid_input", "Order needs at least one line");
    }
    // Merge duplicate products so stock is checked against the total.
    const totals = new Map<string, number>();
    for (const line of lines) {
      if (!Number.isInteger(line.quantity) || line.quantity <= 0) {
        throw new DomainError("invalid_input", "Quantity must be a positive integer");
      }
      totals.set(line.productId, (totals.get(line.productId) ?? 0) + line.quantity);
    }
    const merged: OrderLine[] = [];
    for (const [productId, quantity] of totals) {
      this.mustProduct(productId);
      merged.push({ productId, quantity });
    }
    // Reserve all lines, rolling back if any fails so the order is all-or-nothing.
    const reserved: OrderLine[] = [];
    try {
      for (const line of merged) {
        reserve(this.mustProduct(line.productId), line.quantity);
        reserved.push(line);
      }
    } catch (err) {
      for (const line of reserved) release(this.mustProduct(line.productId), line.quantity);
      throw err;
    }
    const order: Order = {
      id: randomUUID(),
      lines: merged,
      status: "placed",
      createdAt: new Date().toISOString(),
    };
    this.orders.save(order);
    return order;
  }

  getOrder(id: string): Order {
    const order = this.orders.get(id);
    if (!order) throw new DomainError("not_found", `Order ${id} not found`);
    return order;
  }

  listOrders(status?: string, context?: ListOrdersContextDto): Order[] {
    if (status !== undefined && !isOrderStatus(status)) {
      throw new DomainError("invalid_input", `Unknown state ${status}`);
    }
    return this.orders.list(status as OrderStatus | undefined);
  }

  advance(id: string): Order {
    const order = this.getOrder(id);
    const next = nextState(order.status);
    if (next === "shipped") {
      for (const line of order.lines) dispatch(this.mustProduct(line.productId), line.quantity);
    }
    order.status = next;
    this.orders.save(order);
    return order;
  }

  cancel(id: string): Order {
    const order = this.getOrder(id);
    assertCancellable(order);
    for (const line of order.lines) release(this.mustProduct(line.productId), line.quantity);
    order.status = "cancelled";
    this.orders.save(order);
    return order;
  }

  stockLevels(): StockLevel[] {
    return this.products.list().map(toStockLevel);
  }

  stockLevel(productId: string): StockLevel {
    return toStockLevel(this.mustProduct(productId));
  }

  private mustProduct(id: string): Product {
    const product = this.products.get(id);
    if (!product) throw new DomainError("not_found", `Product ${id} not found`);
    return product;
  }
}

export interface ListOrdersContextDto {
  readonly requestId?: string;
}

